package com.weatherlive.wallpaper;
import android.app.*;import android.app.WallpaperManager;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
 TextView info;
 void update(){info.setText("Живі шпалери з реальною погодою\n\n"+WeatherData.status+"\nСцена: "+WeatherData.scene()+"\n\nУвімкніть геолокацію та дозвольте доступ до неї. Погода оновлюється приблизно кожні 15 хвилин, коли шпалери активні.");}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(35,55,35,30);l.setBackgroundColor(Color.rgb(13,23,40));info=new TextView(this);info.setTextColor(Color.WHITE);info.setTextSize(19);l.addView(info);Button permit=new Button(this);permit.setText("1. Дозволити геолокацію");l.addView(permit);permit.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},2);});Button refresh=new Button(this);refresh.setText("2. Оновити погоду");l.addView(refresh);refresh.setOnClickListener(v->{WeatherData.updated=0;new Thread(()->{WeatherData.refresh(getApplicationContext());runOnUiThread(()->update());}).start();});Button apply=new Button(this);apply.setText("3. Встановити живі шпалери");l.addView(apply);apply.setOnClickListener(v->{try{Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,WeatherWallpaper.class));startActivity(i);}catch(Exception e){startActivity(new Intent(WallpaperManager.ACTION_LIVE_WALLPAPER_CHOOSER));}});setContentView(l);update();}
 public void onRequestPermissionsResult(int req,String[] permissions,int[] results){super.onRequestPermissionsResult(req,permissions,results);if(req==2){WeatherData.updated=0;new Thread(()->{WeatherData.refresh(getApplicationContext());runOnUiThread(()->update());}).start();}}
}
